package com.lmspilot.grading.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="grade_results",uniqueConstraints=@UniqueConstraint(name="uq_grade_session",columnNames="session_id"))public class GradeResultEntity{@Id private UUID id=UUID.randomUUID();@Column(name="session_id",nullable=false)private UUID sessionId;@Column(nullable=false)private UUID examId;private UUID enrollmentId;private UUID courseId;private UUID lessonId;@Column(nullable=false)private UUID userId;@Column(nullable=false)private double score;@Column(nullable=false)private double maxScore;@Column(nullable=false)private double percentage;@Column(nullable=false)private double passingScore;@Column(nullable=false)private boolean passed;@Column(nullable=false,length=20)private String scoreStrategy="HIGHEST";@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private GradeStatus status=GradeStatus.AUTO_GRADED;@Column(nullable=false,columnDefinition="text")private String detailsJson="[]";@Column(columnDefinition="text")private String feedback;private UUID gradedBy;@Column(nullable=false)private Instant createdAt=Instant.now();@Column(nullable=false)private Instant updatedAt=Instant.now();@Version private long rowVersion;public GradeResultEntity(){}public GradeResultEntity(UUID sessionId,UUID examId,UUID enrollmentId,UUID courseId,UUID lessonId,UUID userId,double score,double maxScore,double percentage,double passingScore,boolean passed,String strategy,GradeStatus status,String details){this.sessionId=sessionId;this.examId=examId;this.enrollmentId=enrollmentId;this.courseId=courseId;this.lessonId=lessonId;this.userId=userId;this.score=score;this.maxScore=maxScore;this.percentage=percentage;this.passingScore=passingScore;this.passed=passed;this.scoreStrategy=strategy;this.status=status;this.detailsJson=details;}public UUID getId(){return id;}public UUID getSessionId(){return sessionId;}public UUID getExamId(){return examId;}public UUID getEnrollmentId(){return enrollmentId;}public UUID getCourseId(){return courseId;}public UUID getLessonId(){return lessonId;}public UUID getUserId(){return userId;}public double getScore(){return score;}public void setScore(double v){score=v;}public double getMaxScore(){return maxScore;}public double getPercentage(){return percentage;}public void setPercentage(double v){percentage=v;}public double getPassingScore(){return passingScore;}public boolean isPassed(){return passed;}public void setPassed(boolean v){passed=v;}public String getScoreStrategy(){return scoreStrategy;}public GradeStatus getStatus(){return status;}public void setStatus(GradeStatus v){status=v;}public String getDetailsJson(){return detailsJson;}public String getFeedback(){return feedback;}public void setFeedback(String v){feedback=v;}public UUID getGradedBy(){return gradedBy;}public void setGradedBy(UUID v){gradedBy=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}}
